UPDATE email_threads t SET has_calendar_attachment = calc.has_calendar, has_pdf_attachment = calc.has_pdf, has_image_attachment = calc.has_image, has_document_attachment = calc.has_document FROM ( SELECT COALESCE(bool_or(a.filename ILIKE '%.ics' OR a.mime_type = 'text/calendar' OR a.mime_type = 'application/ics'), false) OR EXISTS ( SELECT 1 FROM email_messages im JOIN email_message_calendar_invites i ON i.message_id = im.id WHERE im.thread_id = $1 ) AS has_calendar, COALESCE(bool_or(a.mime_type LIKE ANY($2::text[])), false) AS has_pdf, COALESCE(bool_or(a.mime_type LIKE ANY($3::text[])), false) AS has_image, COALESCE(bool_or(a.mime_type LIKE ANY($4::text[])), false) AS has_document FROM email_messages m JOIN email_attachments a ON a.message_id = m.id WHERE m.thread_id = $1 ) calc WHERE t.id = $1 AND (t.has_calendar_attachment, t.has_pdf_attachment, t.has_image_attachment, t.has_document_attachment) IS DISTINCT FROM (calc.has_calendar, calc.has_pdf, calc.has_image, calc.has_document)
